import json
from fatebridge.services.fengshui import assess
people=[{'subject_id':'a','birth_date':'1990-05-15','gender_convention':'male'},{'subject_id':'b','birth_date':'2000-12-10','gender_convention':'male'},{'subject_id':'c','birth_date':'1990-06-16','gender_convention':'female'}]
base={'methods':['bazhai'],'analyze_layout':True,'placements':[{'object_id':'couple-bed','purpose':'bed','facing_direction':'N','facing_role':'headboard'}]}
out={}
for label,occupants in [('actual_users_only',people[:2]),('all_home_residents',people)]:
 r=assess(**base,occupants=occupants); o=r['layout_analysis']['adjustment_options'][0]
 out[label]={'current_result':o['current_result'],'subjects':[s['subject_id'] for s in o['scopes']],'intersection':o['agreed_matching_directions']}
base['placements'][0]['subject_ids']=['a','b']
try:
 r=assess(**base,occupants=people);o=r['layout_analysis']['adjustment_options'][0]
 out['explicit_subset']={'current_result':o['current_result'],'subjects':[s['subject_id'] for s in o['scopes']],'intersection':o['agreed_matching_directions']}
except Exception as e: out['explicit_subset']={'validation_error':str(e)}
print(json.dumps(out,ensure_ascii=False))
